namespace FaizaCash.Domain;
public class User { public Guid Id { get; set; } = Guid.NewGuid(); public string Login { get; set; } = ""; public string PasswordHash { get; set; } = ""; public string FullName { get; set; } = ""; public bool Active { get; set; } = true; public bool MustChangePassword { get; set; } = true; public List<UserRole> UserRoles { get; set; } = []; }
public class Role { public short Id { get; set; } public string Code { get; set; } = ""; public string Name { get; set; } = ""; }
public class UserRole { public Guid UserId { get; set; } public short RoleId { get; set; } public User User { get; set; } = null!; public Role Role { get; set; } = null!; }
public class RefreshToken { public Guid Id { get; set; } = Guid.NewGuid(); public Guid UserId { get; set; } public User User { get; set; } = null!; public string Hash { get; set; } = ""; public DateTime ExpiresAt { get; set; } public DateTime? RevokedAt { get; set; } public Guid? ReplacedBy { get; set; } }
public class LoginAttempt { public long Id { get; set; } public string Login { get; set; } = ""; public string Ip { get; set; } = ""; public bool Succeeded { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class Currency { public short Id { get; set; } public string Code { get; set; } = ""; public string Name { get; set; } = ""; public byte MinorUnits { get; set; } = 2; }
public class Cashbox { public long Id { get; set; } public string Code { get; set; } = ""; public string Name { get; set; } = ""; public short CurrencyId { get; set; } public Currency Currency { get; set; } = null!; public decimal? BalanceLimit { get; set; } public bool Active { get; set; } = true; public CashboxOpening? Opening { get; set; } }
public class CashboxOpening { public long Id { get; set; } public long CashboxId { get; set; } public Cashbox Cashbox { get; set; } = null!; public DateOnly Date { get; set; } public decimal Amount { get; set; } public Guid CreatedBy { get; set; } }
public class Category { public long Id { get; set; } public string Type { get; set; } = ""; public long? ParentId { get; set; } public string Name { get; set; } = ""; public bool Active { get; set; } = true; }
public class Counterparty { public long Id { get; set; } public string Name { get; set; } = ""; public string Kind { get; set; } = "other"; public string? TaxCode { get; set; } public string? Contact { get; set; } public bool Active { get; set; } = true; }
public class DocumentType { public short Id { get; set; } public string Code { get; set; } = ""; public string Name { get; set; } = ""; public bool Active { get; set; } = true; }
public class CashOperation { public long Id { get; set; } public long CashboxId { get; set; } public DateOnly Date { get; set; } public string Type { get; set; } = ""; public string Status { get; set; } = "draft"; public decimal Amount { get; set; } public string Description { get; set; } = ""; public long CategoryId { get; set; } public Category Category { get; set; } = null!; public long? CounterpartyId { get; set; } public Counterparty? Counterparty { get; set; } public short? DocumentTypeId { get; set; } public string? DocumentNumber { get; set; } public long? ShiftId { get; set; } public long? PostingSeq { get; set; } public bool IsReversal { get; set; } public long? ReversalOfId { get; set; } public long? ReversalId { get; set; } public string? ReversalReason { get; set; } public Guid RequestKey { get; set; } = Guid.NewGuid(); public Guid CreatedBy { get; set; } public User Author { get; set; } = null!; public Guid? PostedBy { get; set; } public DateTime? PostedAt { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public DateTime UpdatedAt { get; set; } = DateTime.UtcNow; public int Version { get; set; } = 1; }
public class DocumentSequence { public long CashboxId { get; set; } public string Type { get; set; } = ""; public short Year { get; set; } public int LastNumber { get; set; } }
public class CashShift { public long Id { get; set; } public long CashboxId { get; set; } public DateOnly Date { get; set; } public string Status { get; set; } = "open"; public decimal OpeningBalance { get; set; } public decimal? ClosingBalance { get; set; } }
public class AuditEvent { public long Id { get; set; } public Guid? UserId { get; set; } public string Action { get; set; } = ""; public string Entity { get; set; } = ""; public long? EntityId { get; set; } public string Details { get; set; } = "{}"; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }

public class CashAccess { public Guid UserId { get; set; } public long CashboxId { get; set; } }
public class Organization { public int Id { get; set; } = 1; public string Name { get; set; } = "ООО «Фаиза»"; public string Currency { get; set; } = "TJS"; public string TimeZone { get; set; } = "Asia/Dushanbe"; }